    {
      "n": "#61·19",
      "text": "This chocolate long-sleeve top has a relaxed, slightly sheer knit that drapes softly over the body, creating an effortless silhouette perfect for layering or wearing on its own during cooler mornings."
    },
    {
      "n": "#208·09",
      "text": "The silvery-grey plaid pencil skirt features a high waist, sharp vertical lines from the check pattern, and a functional front slit that adds subtle movement without sacrificing polish or comfort."
    },
    {
      "n": "#457·12",
      "text": "This chocolate blazer is cut with structured shoulders and clean lapels, giving you a polished outer layer that can be worn open or closed depending on how much coverage you want at any moment."
    },
    {
      "n": "#369·19",
      "text": "The taupe feathered belt sits at the natural waist with a soft fringe detail that catches light and adds texture without bulk, allowing it to cinch your waist gently while still feeling feminine."
    },
    {
      "n": "#411·39",
      "text": "This pink ribbed beanie is slouchy-knit for comfort and warmth, with a snug cuff that holds it in place even when moving through yoga poses or walking briskly outside in the morning."
    },
    {
      "n": "#421·06",
      "text": "These burgundy ballet flats feature a rounded toe, a smooth mesh-like upper, and a low-profile sole that offers quiet comfort without compromising elegance—ideal for hours of standing or walking after yoga."
    },
    {
      "n": "#381·07",
      "text": "This red structured bag has a rectangular shape with a top handle, glossy leather finish, and polished gold-tone hardware that elevates the whole outfit while remaining practical for carrying your daily essentials."
    }
  ]
